import assert from 'node:assert/strict';
export const jointOrder=['shoulder','elbow','wrist','hip','knee','ankle'];
const mappings=[
 ['knee','knee','femoral-cartilage','cartilage'],['knee','knee','tibial-cartilage','cartilage'],['knee','knee','patellar-cartilage','cartilage'],
 ...['acl','pcl','mcl','lcl','patellar-ligament'].map(slug=>['knee','knee',slug,'ligament']),['knee','knee','meniscus-group','meniscus'],
 ['hip','limb','femoral-head-cartilage','cartilage'],
 ['shoulder','fda','ac-ligament','ligament'],['shoulder','fda','humeral-cartilage','cartilage'],['shoulder','fda','labrum','labrum'],
];
const prefix={knee:'vm:reference:um-5t6tz7-v1-2:knee:',limb:'vm:reference:um-5t6tz7-v1-2:lower-limb:',fda:'vm:reference:fda-shoulder-fc9f3e56:'};
const groups=new Set(['tibial-cartilage','meniscus-group']);
const terms=/capsul|labrum|bursa|ligament|cartilage|menisc/i;
const bodyRegions=new Set(['shoulder-arm','forearm','hand','pelvis','thigh','leg','foot']);
const text=x=>{assert(typeof x==='string'&&x.trim()&&x.length<1000);return x;};
function uniqueRows(rows){assert(Array.isArray(rows));const ids=new Set();for(const r of rows){text(r.id);text(r.name);assert(!ids.has(r.id),'Duplicate source identity: '+r.id);ids.add(r.id);}return rows;}

/** Metadata inventory only. Never creates geometry, a correspondence or approval. */
export function buildJointReport({body,nested,pilot,knee,limb,fda,definitions,sourceRevision}){
 assert.match(sourceRevision,/^[a-f0-9]{40}$/);uniqueRows(body);uniqueRows(pilot);assert(Array.isArray(nested));
 const catalogs={knee,limb,fda};for(const c of Object.values(catalogs)){
  uniqueRows(c.structures);assert.equal(c.registeredToBodyParts3D,false);assert.equal(c.imagingRegistration,null);assert.equal(c.source.license,'CC0-1.0');
 }
 assert.equal(fda.clinicalApproval,false);assert.equal(fda.display.anatomicalAxesVerified,false);assert.equal(fda.source.anatomicalSideIndependentlyVerified,false);
 const mapped=mappings.map(([joint,family,slug,tissue])=>{
  const c=catalogs[family],id=prefix[family]+slug,rows=c.structures.filter(r=>r.id===id);assert.equal(rows.length,1,'Exact catalog entry: '+id);const r=rows[0];
  assert.equal(r.slug,slug);assert.equal(r.tissue,tissue);text(r.nodeName);assert.equal(r.validation.anatomicalReview,false);assert.equal(r.validation.registeredToBodyParts3D,false);
  if(family==='fda'){assert.equal(r.laterality,null);assert.equal(r.validation.clinicalApproval,false);assert.equal(r.validation.orientationVerified,false);assert.equal(r.provenance,slug==='humeral-cartilage'?'publisher-reported-offset-constructed':'publisher-reported-CT-segmentation');}
  else assert.equal(r.laterality,'right-source-report');
  const views=family==='fda'?['Independent FDA shoulder']:Object.values(definitions).filter(d=>d.surfaces.some(s=>s.id===id)).map(d=>d.label);assert(views.length,'Source record must be reachable in a current definition');
  return {joint,family,frame:c.specimenId,id,label:r.name,tissue,nodeName:r.nodeName,laterality:r.laterality,sourceReportedSide:c.source.publisherReportedSide??'right',independentlyVerifiedSide:false,grouped:groups.has(slug),constructed:r.provenance==='publisher-reported-offset-constructed',views:[...new Set(views)],license:c.source.license,clinicalApproval:false,bodyRegistered:false,imagingRegistered:false};
 });
 const keys=new Set(mapped.map(r=>r.frame+'|'+r.id));assert.equal(keys.size,mapped.length);assert.equal(mapped.length,13);
 const candidates=[...body.map(r=>({scope:'body-root',...r})),...nested.map(t=>({scope:'nested',parentId:t.parentId,study:t.study,...t.structure}))].filter(r=>bodyRegions.has(r.region)&&terms.test(r.name));
 const exclusions=candidates.filter(r=>/long plantar ligament/i.test(r.name));
 const unresolved=candidates.filter(r=>!exclusions.includes(r));
 const held=fda.held.map(r=>({joint:'shoulder',frame:fda.specimenId,label:r.name,sourcePart:r.sourcePart,reason:r.reason,selectable:false}));assert.equal(held.length,1);assert.equal(held[0].sourcePart,'Gcart');assert(!mapped.some(r=>r.nodeName==='fda_Gcart'));
 const pilotCandidates=pilot.filter(r=>terms.test(r.name));
 return {schema:'vm-joint-soft-tissue-inventory/1',sourceRevision,method:'Exact current metadata and selection-definition inventory. No new geometry, geometry validation, rendering acceptance, clinical approval or patient-space registration.',counts:{bodyRoots:body.length,nestedPlacements:nested.length,shoulderPilot:pilot.length,independentJointEntries:mapped.length,groupedEntries:mapped.filter(r=>r.grouped).length,constructedEntries:mapped.filter(r=>r.constructed).length,heldEntries:held.length},joints:jointOrder.map(id=>({id,label:id[0].toUpperCase()+id.slice(1),entries:mapped.filter(r=>r.joint===id),finding:mapped.some(r=>r.joint===id)?'Mapped independent specimen entries; whole-body integration and clinical validation are not established.':'No exact joint soft-tissue mapping established in this inventory. This is not proof of anatomical absence or complete source coverage.'})),bodyCandidates:unresolved.map(r=>({id:r.id,label:r.name,scope:r.scope,region:r.region,parentId:r.parentId??null,study:r.study??null})),excludedAdjacent:exclusions.map(r=>({id:r.id,label:r.name,reason:'Long plantar ligament is retained as a foot selection; it is not counted as an ankle-joint ligament.'})),pilotCandidates:pilotCandidates.map(r=>({id:r.id,label:r.name})),held,reviewPriorities:[
  'Review the 13 existing independent source entries before commissioning or adding duplicate anatomy; preserve grouped meniscus and tibial cartilage identities.',
  'Review shoulder extent, side and axes; constructed humeral cartilage must remain identified as constructed. Constructed glenoid cartilage remains held.',
  'Define the required capsule, bursa, ligament, labrum, cartilage and meniscus coverage joint by joint, then seek missing commercially compatible sources for elbow, wrist and ankle first.',
  'Assess source frames and attachments separately before any future whole-body placement or imaging correspondence. A matching label does not establish alignment.',
 ],clinicalApproval:false,patientSpaceRegistration:false,completeAnatomy:false,geometryChanged:false,limitations:['Names and exact selection definitions identify source metadata only; mesh continuity, attachment footprints, visibility and usable dissection boundaries were not revalidated.','Teaching mentions do not create separate geometry. The shoulder pilot export is considered separately from independent specimens.','No inference of absent anatomy, complete joint curriculum, new clinical sign-off or permission to register a source into another frame.']};
}
const escape=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderJointReport(report){
 const rows=report.joints.map(j=>`<section id="${escape(j.id)}"><h2>${escape(j.label)} <span>${j.entries.length} mapped entries</span></h2><p>${escape(j.finding)}</p>${j.entries.length?`<ul class="entries">${j.entries.map(r=>`<li><strong>${escape(r.label)}</strong><span class="tag">${escape(r.tissue)}</span>${r.grouped?'<span class="tag">Source group</span>':''}${r.constructed?'<span class="tag">Constructed surface</span>':''}<p>${escape(r.family==='fda'?'Publisher reports right; side and axes unverified.':'Right reported by source; no mirrored left counterpart.')} Independent frame; not registered to whole body or imaging.</p><details><summary>Source and review details</summary><dl><dt>Identity</dt><dd>${escape(r.id)}</dd><dt>Frame</dt><dd>${escape(r.frame)}</dd><dt>Available study views</dt><dd>${escape(r.views.join(' · '))}</dd><dt>Rights in the existing catalogue</dt><dd>${escape(r.license)}</dd></dl></details></li>`).join('')}</ul>`:''}</section>`).join('');
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>Joint soft-tissue inventory · Visible Medicine</title><style>body{margin:0;background:#f5f6ef;color:#123c41;font:16px/1.55 system-ui,sans-serif}main{max-width:1040px;margin:auto;padding:30px 28px}h1{font-size:2rem;margin-bottom:8px}h2{font-size:1.4rem}h2 span{font-size:.9rem;font-weight:400;margin-left:10px}nav{display:flex;flex-wrap:wrap;gap:10px;margin:22px 0}a{color:#124b54;padding:6px 12px;background:white;border:1px solid #8ea9a2;border-radius:8px}a:focus-visible,summary:focus-visible{outline:3px solid #8b5b00;outline-offset:3px}section,.notice{background:white;padding:18px 24px;margin:18px 0;border:1px solid #bfcdc3;border-radius:12px}.entries{padding:0;list-style:none}.entries>li{padding:16px 0;border-top:1px solid #d5dfd8}.tag{display:inline-block;border-radius:5px;padding:1px 7px;margin-left:8px;background:#edf1df;font-size:.85rem}p{max-width:85ch}summary{cursor:pointer;font-weight:600}dt{font-weight:600}dd{margin:0 0 8px;overflow-wrap:anywhere}code{overflow-wrap:anywhere}.muted{color:#47666a}section{scroll-margin-top:20px}@media(max-width:600px){main{padding:18px 12px}section{padding:14px}}</style></head><body><main><header><p class="muted">Visible Medicine · local review preparation</p><h1>Joint soft-tissue inventory</h1><p>What already exists, where it belongs, and what needs further work.</p><p><strong>${report.counts.independentJointEntries} independent entries</strong> · ${report.counts.heldEntries} held surface · ${report.counts.groupedEntries} source groups · ${report.counts.constructedEntries} constructed surface</p></header><div class="notice">This is a metadata inventory, not clinical approval or a new anatomical model. Independent specimen views remain separate from the whole-body Atlas. No scans or patient information are included.</div><nav aria-label="Joints">${report.joints.map(j=>`<a href="#${escape(j.id)}">${escape(j.label)}</a>`).join('')}</nav>${rows}<section><h2>Held separately</h2>${report.held.map(r=>`<p><strong>${escape(r.label)}</strong> — ${escape(r.reason)}. Not counted as selectable.</p>`).join('')}</section><section><h2>Next review priorities</h2><ol>${report.reviewPriorities.map(x=>`<li>${escape(x)}</li>`).join('')}</ol></section><details><summary>Scope, exclusions and exact revision</summary><p>Native source: <code>${escape(report.sourceRevision)}</code></p><p>Inspected ${report.counts.bodyRoots} resolved body roots, ${report.counts.nestedPlacements} nested placements and ${report.counts.shoulderPilot} dedicated shoulder pilot entries alongside independent specimens.</p><p>${report.bodyCandidates.length} unassigned matching body labels; ${report.excludedAdjacent.length} adjacent foot ligament selections excluded from ankle counts.</p><ul>${report.limitations.map(x=>`<li>${escape(x)}</li>`).join('')}</ul></details></main></body></html>`;
}
